import json,html
from pathlib import Path
b=Path(__file__).parent;a=b/'assets';m=json.loads((b/'run-manifest.json').read_text());s=json.loads((a/'source.silence-edl.json').read_text());cuts=json.loads((a/'proposed-cuts.json').read_text())['cuts'];final=s['edited_duration']-sum(c['end']-c['start'] for c in cuts)
def fmt(t):return f'{int(t//60):02d}:{t%60:05.2f}'
intro=f'1.0.mov → 2.0.mov → 3.0.mov · {fmt(m["source_duration"])} original → {fmt(s["edited_duration"])} silence-only → approximately {fmt(final)} after the proposed cuts.'
notes='Preserves the cathedral comparison, pricing and token discussion, Blender OS explanation, backrooms prompt, character generation, Artlist connection walkthrough, final result, and outro. Keeps the emphatic “very, very small prompt” and the useful correction from Plugins to Connectors. Removes abandoned takes, the failed prompt attempt, corrected wording, and accidental repeats.'
md=['# Opus 5.5 Blender / Seedance workflow — cut review','',intro,'',f'**Recommendation: apply all {len(cuts)} proposed cuts.** Final timing remains subject to render verification.','',notes,'','Three stretched tokens were checked against isolated source audio. Those checks recovered two hidden restarts; a fresh transcription of silence-trimmed audio exposed two more doubled words (“environment” and “which”), also confirmed by isolated source transcription.','', 'Each row recommends removing the quoted text and keeping the following wording. Times refer to the original clip.','', '| # | Original clip / time | Remove | Keep immediately after |','|---|---|---|---|'];rows=[]
for c in cuts:
 name=c['source_file'].replace('part','').replace('.mov','.0.mov');tm=fmt(c['local_start'])
 md.append(f'| {c["id"]} | {name} · {tm} | {c["removes"]} | {c["keeps"]} |')
 rows.append(f'<tr><td>{c["id"]}</td><td><button data-src="assets/{c["source_file"]}" data-t="{max(0,c["local_start"]-1.5)}">{name} · {tm}</button></td><td>{html.escape(c["removes"])}</td><td>{html.escape(c["keeps"])}</td></tr>')
md += ['','## Status','','Source transcription, silence planning, whole-transcript editorial review, silence-only audio transcription, and isolated-word checks are complete. Mistake cuts await approval. After approval, render from the original video, freshly transcribe the result, read for residual retakes, and complete the silence, cuts, and ledger verification passes.']
(b/'CUT-REVIEW.md').write_text('\n'.join(md)+'\n')
(b/'review.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Opus 5.5 — cut review</title><style>body{background:#10151d;color:#e6edf7;font:16px/1.5 system-ui;max-width:1320px;margin:28px auto;padding:0 24px}video{width:100%;position:sticky;top:0;max-height:42vh;background:#000}table{border-collapse:collapse;width:100%}td,th{padding:12px;border-bottom:1px solid #344050;text-align:left;vertical-align:top}td:nth-child(2){min-width:150px}button,a{color:#99cfff}button{background:#223349;border:1px solid #527093;border-radius:5px;padding:6px;cursor:pointer}h1{font-size:28px}.sub{color:#abbacd}</style><h1>Opus 5.5 Blender / Seedance workflow</h1>'''+f'<p class="sub">{intro}</p><p><strong>52 proposed cuts — awaiting approval</strong></p><p>{notes}</p>'+'''<p>Click a timestamp to play the original clip with context. <a href="CUT-REVIEW.md">Written cut list</a></p><video id="v" src="assets/part1.mov" controls preload="metadata"></video><table><thead><tr><th>#</th><th>Original clip / time</th><th>Remove</th><th>Keep following</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table><script>const v=document.getElementById('v');document.querySelectorAll('button').forEach(b=>b.onclick=()=>{const go=()=>{v.currentTime=Number(b.dataset.t);v.play().catch(()=>{})};if(v.getAttribute('src')!==b.dataset.src){v.src=b.dataset.src;v.addEventListener('loadedmetadata',go,{once:true})}else go()})</script></html>''')
(b/'meta.json').write_text(json.dumps(dict(title='Opus 5.5 Blender and Seedance Workflow',status='awaiting-cut-approval',width=3840,height=1080,fps=30,pipeline=['cut-silences','cut-mistakes','verify-cuts'],proposed_cuts=len(cuts),source_seconds=m['source_duration'],estimated_final_seconds=final),indent=2))
(b/'NOTES.md').write_text(f'# Awaiting cut approval\n\n{intro}\n\n52 cuts recommended. Review CUT-REVIEW.md or review.html. Source videos are symlinked as assets/part1.mov through part3.mov. No mistake cuts have been applied. After approval, render directly from originals and run fresh transcription, retake read, and three verification passes.\n')
print(intro)
